INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (93830,0,0,0,0,'Drink if you must while you''re at the pond, as long as you fill the waterskin back up ere you bring it back.',71037);
