INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (93833,0,0,0,0,'The owls, while sleek and serene, are capable of viciously ending life in moments. Be alert!',71037);
